CREATE OR REPLACE FUNCTION public.admin_push_adoption()
 RETURNS TABLE(creator_id uuid, name text, is_admin boolean, devices bigint, first_enabled timestamp with time zone, chat_push_on boolean, last_seen_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
